components.css:
.ds-primary-button{ display: flex; align-items: center; justify-content: center; gap: 10px; border: 0; border-radius: 10px; background: var(--primary); color: #fff; font-weight: 600; padding: 0 25px; min-height: 54px; white-space: nowrap; transition: background .18s; }
.ds-primary-button:hover:not(:disabled){ background: #183caa; }
.ds-primary-button{ min-height: 46px; font-size: 14px; }
.ds-primary-button:focus-visible{outline:3px solid #2453dd;outline-offset:4px}

.ds-open-button{ display: flex; align-items: center; justify-content: center; gap: 8px; border-radius: 7px; min-height: 41px; font-size: 14px; font-weight: 550; }
.ds-open-button{ background: #eef2ff; color: #244bbe; }
.ds-open-button:hover{ background: #dee7ff; }
.ds-open-button:focus-visible{outline:3px solid #2453dd;outline-offset:4px}

.ds-check-button{ display: flex; align-items: center; justify-content: center; gap: 8px; border-radius: 7px; min-height: 41px; font-size: 14px; font-weight: 550; }
.ds-check-button{ color: #4c5a73; background: #fff; border: 1px solid #dbe1eb; }
.ds-check-button:hover:not(:disabled){ background: #f5f7fb; border-color: #a8b8df; }
.ds-check-button:focus-visible{outline:3px solid #2453dd;outline-offset:4px}

.ds-search-wrap{ border: 1px solid #cbd4e4; border-radius: 10px; display: flex; align-items: center; gap: 12px; flex: 1; min-width: 0; background: #fff; padding: 0 18px; color: var(--muted-foreground); height: 54px; }
.ds-search-wrap:focus-within{ border-color: var(--primary); outline: 2px solid #2453dd20; }
.ds-search-wrap input{ border: none; background: transparent; outline: 0; width: 100%; min-width: 0; color: var(--foreground); }
.ds-search-wrap input::placeholder{ color: #65728a; }
.ds-search-wrap button{ display: grid; place-items: center; background: transparent; border: 0; width: 32px; height: 36px; }
.ds-search-wrap{ flex-basis: auto; height: 50px; flex-shrink: 0; }
.ds-search-wrap:focus-visible{outline:3px solid #2453dd;outline-offset:4px}

.ds-category-tab{ padding: 10px 14px; min-height: 42px; font-size: 14px; font-weight: 550; color: #58647a; border: 0; border-radius: 8px; gap: 8px; }
.ds-category-tab[data-state="active"]{ color: #244bbe; background: #e6edff; box-shadow: none; }
.ds-category-tab:hover{ background: #eaf0ff; }
.ds-category-tab{ padding: 10px 9px; gap: 5px; font-size: 13px; }
.ds-category-tab:focus-visible{outline:3px solid #2453dd;outline-offset:4px}

.ds-site-card{ background: #fff; border: 1px solid #dde3ed; border-radius: 14px; padding: 23px; transition: border-color .2s; min-width: 0; }
.ds-site-card:hover{ border-color: #a8b8df; }
.ds-site-card.is-checking{ border-color: #2453dd; }
.ds-site-card{ padding: 21px; }
.ds-site-card{ padding: 22px; }
.ds-site-card:focus-visible{outline:3px solid #2453dd;outline-offset:4px}
